    source_meta = source_meta.replace('let runFailedCooldownUntil = 0;', '')
    source_meta = source_meta.replace('export let runStaleCooldownUntil = 0;', 'export const batchRunCooldowns = { staleUntil: 0, failedUntil: 0 };')
    source_meta = source_meta.replace('export let runFailedCooldownUntil = 0;', '')
